window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b634aefc2c547aca"]={"versions": [{"id": "FIG-b634aefc2c547aca", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontroll- und Datenflusses der Wrapper-Funktion <code>E2EPW_Write</code> im Rahmen des AUTOSAR E2E-Schutzes (E2E Protection Wrapper). Das Diagramm veranschaulicht die senderseitige Kapselung zwischen Applikations-Software-Komponente (SW-C), AUTOSAR E2E-Bibliothek (<code>E2E_PXXProtect</code>) und der AUTOSAR-Laufzeitumgebung (<code>Rte_Write_&lt;p&gt;_&lt;o&gt;</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Funktionen & Schnittstellen:</strong></li>\n<li><code>E2EPW_Write</code>: Wrapper-Funktion zum geschützten Schreiben von Daten.</li>\n<li><code>E2E_PXXProtect(Config, State, Data)</code>: Schutzfunktion der AUTOSAR E2E-Bibliothek (Profil <code>XX</code>).</li>\n<li><code>Rte_Write_&lt;p&gt;_&lt;o&gt;(AppDataEl)</code>: Sender-API der RTE zur Übertragung des geschützten Datenelements über Port <code>&lt;p&gt;</code> und Datenelement <code>&lt;o&gt;</code>.</li>\n<li><strong>Datenobjekte & Parameter:</strong></li>\n<li><code>AppDataEl</code>: Zeiger bzw. Referenz auf das Anwendungsdatenelement (Eingabeparameter).</li>\n<li><code>Data</code>: Interne Repräsentation des Datenpakets (IPDU-Repräsentation als Byte-Array).</li>\n<li><code>Config</code>, <code>State</code>: Konfigurationsstruktur und Zustandsstruktur des E2E-Profils.</li>\n<li><strong>Lokale Status- & Rückgabevariablen:</strong></li>\n<li><code>retRteWrite</code>: Rückgabestatus des RTE-Schreibaufrufs (initialisiert mit <code>RTE_E_OK</code>).</li>\n<li><code>retE2EProtect</code>: Rückgabestatus der E2E-Schutzberechnung (initialisiert mit <code>E2E_E_OK</code>).</li>\n<li><code>plausibilityChecks</code>: Status interner Plausibilitätsprüfungen (initialisiert mit <code>E2E_E_OK</code>).</li>\n<li><code>ret</code>: Zusammengesetzter 32-Bit-Rückgabewert der Funktion.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Start und Initialisierung:</strong> Einstieg über den Startknoten; Initialisierung der Variablen <code>retRteWrite</code>, <code>retE2EProtect</code> und <code>plausibilityChecks</code> mit dem Wert <code>E2E_E_OK</code> bzw. <code>RTE_E_OK</code>.</li>\n<li><strong>Plausibilitätsprüfung:</strong> Verzweigung anhand der Bedingung <code>AppDataEl == NULL</code>.</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zweig <code>[TRUE]</code>: Zuweisung <code>plausibilityChecks = E2E_E_INPUTERR_NULL</code>; direkter Übergang zum Zusammenführungsknoten.</li>\n<li>Zweig <code>[FALSE]</code>: Serialisierung von <code>AppDataEl</code> in die IPDU-Repräsentation <code>Data</code> (falls <code>AppDataEl</code> komplex ist) bzw. Kopieren als Byte-Array nach <code>Data</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>E2E-Absicherung:</strong> Aufruf von <code>retE2EProtect = E2E_PXXProtect(Config, State, Data)</code>.</li>\n<li><strong>Schutzstatusprüfung:</strong> Verzweigung anhand der Bedingung <code>retE2EProtect == E2E_E_OK</code>.</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zweig <code>[TRUE]</code>: Zurückschreiben von CRC und Counter aus <code>Data</code> in das Originaldatenelement <code>AppDataEl</code>, gefolgt vom Senden der Daten via <code>retRteWrite = Rte_Write_&lt;p&gt;_&lt;o&gt;(AppDataEl)</code>.</li>\n<li>Zweig <code>[FALSE]</code>: Überspringen des Rückschreibens und des RTE-Schreibaufrufs; direkter Übergang zum Zusammenführungsknoten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Ergebnisbildung & Abschluss:</strong> Am Zusammenführungsknoten werden die Statuswerte bitweise kombiniert zu <code>ret = retRteWrite | (retE2EProtect &lt;&lt; 8) | (plausibilityChecks &lt;&lt; 16)</code>. Beenden der Funktion am Endknoten mit Rückgabe von <code>ret</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert das normative Ausführungsverhalten für senderseitige E2E-Wrapper-Generatoren oder Implementierungen:</p>\n<ul class=\"fig-list\">\n<li>Ein NULL-Zeiger (<code>AppDataEl == NULL</code>) führt zum Abbruch der Serialisierung und Übertragung unter Setzen von <code>E2E_E_INPUTERR_NULL</code> im höchstwertigen Byte-Segment von <code>ret</code>.</li>\n<li>Der RTE-Aufruf <code>Rte_Write</code> darf strikt nur erfolgen, wenn die E2E-Schutzroutine fehlerfrei (<code>retE2EProtect == E2E_E_OK</code>) durchlaufen wurde.</li>\n<li>Die berechneten Schutzdaten (CRC, Sequenzzähler) werden vor der eigentlichen RTE-Übertragung explizit in die Applikationsdatenstruktur <code>AppDataEl</code> synchronisiert.</li>\n<li>Das Fehlerschema kodiert RTE-, Schutz- und Plausibilitätsstatus orthogonal in einem einzigen Rückgabewert via Bitshift-Maskierung (<code>retRteWrite</code> in Bits 0..7, <code>retE2EProtect</code> in Bits 8..15, <code>plausibilityChecks</code> in Bits 16..23).</li>\n</ul>"}, {"id": "FIG-4664312d674237cf", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontroll- und Datenflusses der Wrapper-Funktion <code>E2EPW_Write</code> im Rahmen des AUTOSAR E2E-Schutzes (E2E Protection Wrapper). Das Diagramm veranschaulicht die senderseitige Kapselung zwischen Applikations-Software-Komponente (SW-C), AUTOSAR E2E-Bibliothek (<code>E2E_PXXProtect</code>) und der AUTOSAR-Laufzeitumgebung (<code>Rte_Write_&lt;p&gt;_&lt;o&gt;</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Funktionen & Schnittstellen:</strong></li>\n<li><code>E2EPW_Write</code>: Wrapper-Funktion zum geschützten Schreiben von Daten.</li>\n<li><code>E2E_PXXProtect(Config, State, Data)</code>: Schutzfunktion der AUTOSAR E2E-Bibliothek (Profil <code>XX</code>).</li>\n<li><code>Rte_Write_&lt;p&gt;_&lt;o&gt;(AppDataEl)</code>: Sender-API der RTE zur Übertragung des geschützten Datenelements über Port <code>&lt;p&gt;</code> und Datenelement <code>&lt;o&gt;</code>.</li>\n<li><strong>Datenobjekte & Parameter:</strong></li>\n<li><code>AppDataEl</code>: Zeiger bzw. Referenz auf das Anwendungsdatenelement (Eingabeparameter).</li>\n<li><code>Data</code>: Interne Repräsentation des Datenpakets (IPDU-Repräsentation als Byte-Array).</li>\n<li><code>Config</code>, <code>State</code>: Konfigurationsstruktur und Zustandsstruktur des E2E-Profils.</li>\n<li><strong>Lokale Status- & Rückgabevariablen:</strong></li>\n<li><code>retRteWrite</code>: Rückgabestatus des RTE-Schreibaufrufs (initialisiert mit <code>RTE_E_OK</code>).</li>\n<li><code>retE2EProtect</code>: Rückgabestatus der E2E-Schutzberechnung (initialisiert mit <code>E2E_E_OK</code>).</li>\n<li><code>plausibilityChecks</code>: Status interner Plausibilitätsprüfungen (initialisiert mit <code>E2E_E_OK</code>).</li>\n<li><code>ret</code>: Zusammengesetzter 32-Bit-Rückgabewert der Funktion.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Start und Initialisierung:</strong> Einstieg über den Startknoten; Initialisierung der Variablen <code>retRteWrite</code>, <code>retE2EProtect</code> und <code>plausibilityChecks</code> mit dem Wert <code>E2E_E_OK</code> bzw. <code>RTE_E_OK</code>.</li>\n<li><strong>Plausibilitätsprüfung:</strong> Verzweigung anhand der Bedingung <code>AppDataEl == NULL</code>.</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zweig <code>[TRUE]</code>: Zuweisung <code>plausibilityChecks = E2E_E_INPUTERR_NULL</code>; direkter Übergang zum Zusammenführungsknoten.</li>\n<li>Zweig <code>[FALSE]</code>: Serialisierung von <code>AppDataEl</code> in die IPDU-Repräsentation <code>Data</code> (falls <code>AppDataEl</code> komplex ist) bzw. Kopieren als Byte-Array nach <code>Data</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>E2E-Absicherung:</strong> Aufruf von <code>retE2EProtect = E2E_PXXProtect(Config, State, Data)</code>.</li>\n<li><strong>Schutzstatusprüfung:</strong> Verzweigung anhand der Bedingung <code>retE2EProtect == E2E_E_OK</code>.</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zweig <code>[TRUE]</code>: Zurückschreiben von CRC und Counter aus <code>Data</code> in das Originaldatenelement <code>AppDataEl</code>, gefolgt vom Senden der Daten via <code>retRteWrite = Rte_Write_&lt;p&gt;_&lt;o&gt;(AppDataEl)</code>.</li>\n<li>Zweig <code>[FALSE]</code>: Überspringen des Rückschreibens und des RTE-Schreibaufrufs; direkter Übergang zum Zusammenführungsknoten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Ergebnisbildung & Abschluss:</strong> Am Zusammenführungsknoten werden die Statuswerte bitweise kombiniert zu <code>ret = retRteWrite | (retE2EProtect &lt;&lt; 8) | (plausibilityChecks &lt;&lt; 16)</code>. Beenden der Funktion am Endknoten mit Rückgabe von <code>ret</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert das normative Ausführungsverhalten für senderseitige E2E-Wrapper-Generatoren oder Implementierungen:</p>\n<ul class=\"fig-list\">\n<li>Ein NULL-Zeiger (<code>AppDataEl == NULL</code>) führt zum Abbruch der Serialisierung und Übertragung unter Setzen von <code>E2E_E_INPUTERR_NULL</code> im höchstwertigen Byte-Segment von <code>ret</code>.</li>\n<li>Der RTE-Aufruf <code>Rte_Write</code> darf strikt nur erfolgen, wenn die E2E-Schutzroutine fehlerfrei (<code>retE2EProtect == E2E_E_OK</code>) durchlaufen wurde.</li>\n<li>Die berechneten Schutzdaten (CRC, Sequenzzähler) werden vor der eigentlichen RTE-Übertragung explizit in die Applikationsdatenstruktur <code>AppDataEl</code> synchronisiert.</li>\n<li>Das Fehlerschema kodiert RTE-, Schutz- und Plausibilitätsstatus orthogonal in einem einzigen Rückgabewert via Bitshift-Maskierung (<code>retRteWrite</code> in Bits 0..7, <code>retE2EProtect</code> in Bits 8..15, <code>plausibilityChecks</code> in Bits 16..23).</li>\n</ul>"}], "trans": [{"from": "FIG-b634aefc2c547aca", "to": "FIG-4664312d674237cf", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
